datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Product {
  id         Int         @id @default(autoincrement())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    Int    @id @default(autoincrement())
  code  String @unique
  type  String // "PERCENT" or "FLAT"
  value Float
}

model Order {
  id         Int         @id @default(autoincrement())
  createdAt  DateTime    @default(now())
  subtotal   Float
  discount   Float
  total      Float
  couponCode String?
  orderItems OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  orderId   Int
  order     Order   @relation(fields: [orderId], references: [id])
  productId Int
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
  price     Float
}

import type { PrismaClient } from '@prisma/client'

export async function devSeed(prisma: PrismaClient) {
  // Seed Products
  await prisma.product.upsert({
    where: { id: 1 },
    update: {
      name: "Premium Wireless Headphones",
      price: 100.0,
      inventory: 10,
    },
    create: {
      id: 1,
      name: "Premium Wireless Headphones",
      price: 100.0,
      inventory: 10,
    },
  });

  await prisma.product.upsert({
    where: { id: 2 },
    update: {
      name: "Ergonomic Mechanical Keyboard",
      price: 150.0,
      inventory: 1,
    },
    create: {
      id: 2,
      name: "Ergonomic Mechanical Keyboard",
      price: 150.0,
      inventory: 1,
    },
  });

  // Seed Coupons
  await prisma.coupon.upsert({
    where: { code: "SAVE20" },
    update: {
      type: "PERCENT",
      value: 20.0,
    },
    create: {
      code: "SAVE20",
      type: "PERCENT",
      value: 20.0,
    },
  });

  await prisma.coupon.upsert({
    where: { code: "FLAT50" },
    update: {
      type: "FLAT",
      value: 50.0,
    },
    create: {
      code: "FLAT50",
      type: "FLAT",
      value: 50.0,
    },
  });

  console.log("Database seeded successfully!");
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };
import { getProducts, validateCoupon } from "./src/queries" with { type: "ref" };
import { checkout } from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProducts, { entities: ["Product"] }),
